function BBP.ApplyProfile(profileName)
    local profile
    for _, p in ipairs(BBP.ProfileData) do
        if p.name == profileName then
            profile = p
            break
        end
    end
    if not profile then
        BBP.Print("Profile not found: " .. tostring(profileName))
        return
    end

    local profileData, errorMessage = BBP.OldImportProfile(profile.importString, "fullProfile")
    if errorMessage then
        print("|A:gmchat-icon-blizz:16:16|aBetter|cff00c0ffBlizz|rPlates: Error importing profile:", errorMessage)
    else
        for k in pairs(BetterBlizzPlatesDB) do BetterBlizzPlatesDB[k] = nil end
        for k, v in pairs(profileData) do
            BetterBlizzPlatesDB[k] = v
        end
        BetterBlizzPlatesDB.scStart = true
        BetterBlizzPlatesDB.skipUpdateMsg = true
        C_CVar.SetCVar("nameplateShowFriendlyPlayers", "1")
        -- Midnight: if the imported profile has Totem Indicator enabled, fix the CVars for it to work properly
        if BetterBlizzPlatesDB.totemIndicator then
            BetterBlizzPlatesDB.nameplateShowEnemyGuardians = "0"
            BetterBlizzPlatesDB.nameplateShowEnemyMinions = "0"
            BetterBlizzPlatesDB.totemIndicatorUpdatedForMidnight = true
        end
        if BetterBlizzPlatesDB.nameplateResourceOnTarget and EditModeManagerFrame and EditModeManagerFrame.AccountSettings and EditModeManagerFrame.AccountSettings.RefreshPersonalResourceDisplay then
            local personalResourceDisplayEnabled = EditModeManagerFrame:GetAccountSettingValueBool(Enum.EditModeAccountSetting.ShowPersonalResourceDisplay)
            if not personalResourceDisplayEnabled then
                EditModeManagerFrame:OnAccountSettingChanged(Enum.EditModeAccountSetting.ShowPersonalResourceDisplay, true)
                EditModeManagerFrame.AccountSettings:RefreshPersonalResourceDisplay()
            end
        end
        BetterBlizzPlatesDB.avoidPopups = true
        ReloadUI()
    end
end